    ["и§Јй”Ѓж‰Ђжњ‰зі»з»џпјЊеЉ buffи°ѓжЉЂиѓЅпјЊиѕѕе€°CBT2зљ„90зє§"] = "Р Р°Р·Р±Р»РѕРєРёСЂСѓР№С‚Рµ РІСЃРµ СЃРёСЃС‚РµРјС‹, РґРѕР±Р°РІСЊС‚Рµ Р±Р°С„С„С‹, РЅР°СЃС‚СЂРѕР№С‚Рµ РЅР°РІС‹РєРё, РґРѕСЃС‚РёРіРЅРёС‚Рµ 90 СѓСЂРѕРІРЅСЏ Р—Р‘Рў2.",
